fn first_positive(v: &Vec[Int]) -> Option[Int] {
  var i = 0;
  while i < v.len() {
    if v[i] > 0 {
      return Some(v[i]);
    }
    i = i + 1;
  }
  return None;
}

fn divide_safe(a: Float64, b: Float64) -> Option[Float64] {
  if b == 0.0 {
    return None;
  }
  return Some(a / b);
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(-1);
  v.push(0);
  v.push(5);
  v.push(-3);
  match first_positive(&v) {
    Some(val) => { return val; }
    None => { return -1; }
  }
}
